"""Nur Aggregate und Definitionen in Projektberichte exportieren."""
def run():
    import json,csv,time
    from werkzeuge.b_test.aw166_run import OUT,ROOT,sha,dump
    def load(name):return json.loads((OUT/name).read_text(encoding='utf8'))
    morph=load('morphology.json');cal=load('calibration.json');models=load('model_results.json');gate=load('signal_gate.json');prep=load('prepare_manifest.json')
    protocol=load('protokoll_hash.json');rows=[]
    def num(v):return f'{v:.4g}'
    def interval(v):return 'nicht schätzbar' if v is None else f'[{num(v[0])}; {num(v[1])}]'
    def interval_en(v):return 'not estimable' if v is None else f'[{num(v[0])}, {num(v[1])}]'
    complete=gate['state']=='passed'
    text=['# AW-166 - EF-abhängiger T-Ende-Fehler','', '13.10.2026 · MS/PR · Rechenspur R · explorative Entwicklung, train/validation · Standards 02 v1.2.','']
    if complete:
        corrected=[r for r in models if r['scenario']=='corrected']
        text += ['## Ergebnis zuerst','', 'Die T-Morphologie unterscheidet sich nach EF. Die Abbruchregel ist nicht erfüllt. Das LUDB-Modell ergibt eine kleine erwartete differenzielle T-Ende-Verschiebung; die individuelle Korrektur und die modellgebundene Einordnung stehen unten. Eine kausale Zerlegung des Fréchet-Zusatzes wird daraus nicht abgeleitet.','']
        for r in corrected:text.append(f"{r['fold']}: korrigierte OR {num(r['or'])} {interval(r['or_ci95'])}; verbleibender log-OR-Anteil {num(r['remaining_log_or_fraction'])} {interval(r['fraction_ci95'])}; vorgegebene Kategorie: **{r['classification']}**.")
        if any(r['or_ci95'] is None for r in corrected):text += ['', '**Kein belastbarer Robustheitsnachweis:** Mindestens ein Korrekturintervall ist wegen des Bootstrap-Ausfallgates nicht schätzbar. Die Kategorien beschreiben dann nur die Punktschätzungen unter dem Mittelfehlermodell.']
    else:
        text += ['## Ergebnis zuerst','', '**Die individuelle Übertragung ist nicht freigegeben: Die produktionsgleiche Äquivalenzprüfung scheiterte.** Keine korrigierte Fréchet-OR und keine Kategorie nach Punkt 4 des Auftrags. Morphologie und LUDB-Kalibrierung sind separat berechnet; die diskretisierten Gruppen-/Worst-Case-Verschiebungen sind identisch null. Das ist kein Nachweis, dass reale differenzielle Messfehler fehlen.','']
    text += ['', '## 1. Vorabbindung, Fallset und Nenner','',f"Erstes Artefakt `werkzeuge/b_test/aw166_protokoll.md`, SHA-256 `{protocol['sha256']}`, Zeitbindung `{protocol['utc']}` vor neuer Individualdatensicht/Rechnung. Auftrag und frühere Berichte waren bekannt; der lokale Hash beweist keine externe Präregistrierung.", '',f"H1-B3: unveränderte masks/classify_lvef aus daten.py und raw_design/fixed_design aus statistik.py. LVEF <40 gegen ≥40, wertblind gewählter erster verifizierter erwachsener Index, bekannte eligible Referenz, Konfliktflag ausdrücklich false, passende nearest-TTE-/Evidence-ID, timestamp und ±720 h. Keine Ersatzindizes oder Imputation. Train/validation personendisjunkt. Feste Entwicklungs-Skalierung, F-SD {num(prep['entry']['scaling_B3']['sd'][-1])}; Alter (natürliche Basis), Geschlecht, gebundene HF, QRS, QTcF, linearer Winkel und Fréchet. QRS nicht doppelt. QTcF und andere Nuisance-Kovariaten bleiben im gezielten Marker-Störversuch gebunden.", '',f"Fallfluss: `{json.dumps(prep['flow']['sequential'])}`. Eingabe AW131 `BEF-0063_entwicklung.parquet`, SHA-256 `{prep['sources'][prep['entry']['input_development']['path']]['sha256']}`. Keine Testdatei/-identität/-Ergebnisdatei geöffnet. Validation ist interne Bestätigung, keine unabhängige Prüfung.",'','## 2. Morphologie nach EF','', 'T-Spitzenamplitude = Produktionsmerkmal t_vector_magnitude /1000 (µV→mV), Maximum des ursprungskorrigierten räumlichen Kors-T-Vektors. Dauer = Produktionsmerkmal t_duration_ms, T-Onset bis T-Ende; Flachheit = Amplitude/Dauer (mV/ms). SNR = Amplitude / (1,4826 × MAD der zweiten räumlichen Differenzen des repräsentativen T-Abschnitts /√6). Dies ist ein eigener Rauschproxy, kein physikalisch validiertes Mess-SNR; glatte T-Krümmung und Filterung beeinflussen ihn. loop_snr_proxy wurde ausdrücklich nicht als T-SNR benutzt (QRS/PR-Definition im Release).','', 'SMD niedrig minus erhalten / √((s²_niedrig+s²_erhalten)/2), keine gewichtete Gesamt-SD. 500 Personenresamples einschließlich fehlender Werte, 95%-Perzentil-KI, Seed 16620261013; Quantile 5/25/50/75/95%. Ein Index pro Person, deshalb entspricht Zeilenresampling dem Personenbootstrap. Nominale, nicht simultane KI.','', '| Fold | Maß | n <40 / ≥40 | Fehlend <40 / ≥40 | Mittel <40 / ≥40 | SMD [95%-KI] |','|---|---|---:|---:|---:|---:|']
    for r in morph:
        text.append(f"| {r['fold']} | {r['measure']} | {r['n_low']} / {r['n_high']} | {r['missing_low']} / {r['missing_high']} | {num(r['mean_low'])} / {num(r['mean_high'])} | {num(r['smd'])} [{num(r['smd_ci_low'])}; {num(r['smd_ci_high'])}] |")
        rows.append({'section':'morphology',**r,'source':'A155 cache split=train/validation; H1-B3 index join; aw166_run.py:morphology; <local path>'})
    text += ['', 'Alle Gruppenmittel-, Quantil-KI und Quantilwerte stehen in b_tende_ef.csv (JSON-Felder mit gleicher Gruppenreihenfolge). Die Abbruchregel scheitert bereits an der T-Dauer; fehlendes SNR darf nicht als bestandenes Maß zählen. Morphologieunterschiede beweisen selbst keinen Grenzfehler.', '', '## 3. LUDB-Fehlermodell und Transport','', f"Alle 200 LUDB-Aufzeichnungen mit dem gebundenen Release neu vorbereitet und delineiert (500 Hz, Netzparameter 50 Hz). Sämtliche T-Enden gegen die vollständigen AW147-Vorhersagen exakt gleich. Keine neue Grenzoptimierung. AW140-QRS-verankerte Paare, scope=fused_global, landmark=t_offset, ohne Fehlertrimming; Fehler Produktion minus extreme Expertenreferenz. Modell auf {cal['n_records']} morphologisch vollständigen Personenaufzeichnungen mit {cal['n_beats']} endlichen Beatfehlern / {cal['n_reference']} Referenzzeilen. Fehlende Morphologie schließt Aufzeichnungen aus, kein Ersatz. Recordmittel des Grenzfehlers als Ziel; jede Person hat gleiches Gewicht. Lineare Regression mit Interzept, Amplitude und Flachheit gemeinsam; HC3 robuste Standardfehler auf der unabhängigen Recordebene, keine Beat-Pseudoreplikation. Die Referenz ist die globale extreme Fusion (spätestes Expertenende), nicht ein adjudiziertes latentes physiologisches T-Ende.", '', '| Parameter | Schätzer | Robuster SE | 95%-KI |','|---|---:|---:|---:|']
    for i,k in enumerate(cal['columns']):
        text.append(f"| {k} | {num(cal['params'][i])} | {num(cal['se_robust_HC3'][i])} | {interval(cal['ci95_robust_HC3'][i])} |")
        rows.append({'section':'calibration_parameter','measure':k,'estimate':cal['params'][i],'se':cal['se_robust_HC3'][i],'ci_low':cal['ci95_robust_HC3'][i][0],'ci_high':cal['ci95_robust_HC3'][i][1],'n_records':cal['n_records'],'n_beats':cal['n_beats'],'source':'AW140 errors + AW147 predictions + public LUDB signals; aw166_run.py:ludb/calibrate; calibration.json'})
    text += ['',f"Recordresidual-SD {num(cal['residual_sd_record_ms'])} ms; R² {num(cal['r_squared'])}. Diese SD ist die Streuung der Recordmittel, nicht die Beatfehler-SD oder ein individuelles Fehlerintervall. Erwarteter Fehler <40 / ≥40: {num(cal['mean_shift_low'])} / {num(cal['mean_shift_high'])} ms. Differenz {num(cal['group_difference_ms'])} ms {interval(cal['group_difference_ci95_ms'])}. KI aus 500 gemeinsamen Resamples der LUDB-Records und Entwicklungspersonen, Kalibrierung jeweils neu geschätzt.", '',f"LUDB-Merkmalsbereiche: `{json.dumps(cal['ludb_range'])}`; außerhalb der marginalen Bereiche in MIMIC: `{json.dumps(cal['outside_range'])}` / 33971. Kein Clipping, kein als validiert behaupteter Transport. Marginale Bereichsabdeckung garantiert keine gemeinsame Kovariatensupport-Überlappung. LUDB ist bereits Entwicklungsreferenz, keine unabhängige Validierung; sie hat keine EF-Labels für eine direkte EF×Grenzfehler-Schätzung. QTDB wurde in AW147 nicht neu gerechnet und bietet keine echte zwölfkanalige Kors-/Dreiableitungsfusion. Daher keine QTDB-Kalibrierung erfunden.",'','## 4. Übertragung, Fréchet und H1-B3','', 'Korrigiertes Ende = Produktionsende minus erwarteter Morphologiefehler. Alle vorhandenen Beat-T-Enden verschoben, repräsentative Grenzen/Marker vom Release neu erzeugt. Verschiebungen auf ganzzahlige Samples gerundet (500 Hz: 2 ms). Gruppensensitivität: erwartete Differenz zusätzlich nur in der <40-Gruppe eingespielt. Worst-Case: maximale absolute Grenze des zweiseitigen 95%-KI der Gruppendifferenz, beide Vorzeichen. Das KI liegt vollständig negativ; die maximale absolute Grenze ist die konservative Betragsschanke. Hier runden Gruppenverschiebung und Worst-Case beide auf 0 Samples. Ihre OR und log-OR-Anteile bleiben daher algebraisch unverändert; die Degeneriertheit ist Auflösungsbindung, keine physiologische Äquivalenz.','',f"Signal-Äquivalenzgate: `{json.dumps(gate)}`.", '', '| Fold | Szenario | n / Fälle | OR [95%-KI] | verbleibender log-OR [95%-KI] | Bootstrap |','|---|---|---:|---:|---:|---:|']
    for r in models:
        text.append(f"| {r['fold']} | {r['scenario']} | {r['n']} / {r['cases']} | {num(r['or'])} {interval(r['or_ci95'])} | {num(r['remaining_log_or_fraction'])} {interval(r['fraction_ci95'])} | {str(r['bootstrap_valid'])+'/'+str(r['bootstrap_requested']) if r['bootstrap_requested'] else 'CR1-Wald'} |")
        rows.append({'section':'B3_model',**{k:v for k,v in r.items() if k!='failures'}})
    text += ['', 'OR je fester gemessener Entwicklungs-SD des Fréchet-Markers. Anteil = korrigierter/originaler log-OR, kein OR-Quotient und keine Begrenzung auf 100%. Gemeinsame endliche Original-/Korrekturfälle, Ausschlüsse in CSV. 500 gepaarte Personenbootstrapziehungen pro Fold; LUDB-Koeffizienten je Draw erneuert. Alle dafür benötigten diskreten Sampleverschiebungen je EKG exakt aus dem Release gerechnet, keine Markerinterpolation. Nichtendliche aktive Korrekturwerte invalidieren einen Draw; keine Ersatzziehungen; KI erst bei ≥475 gültigen Draws. Die festen Gruppen-/Worst-Case-Szenarien konditionieren auf ihre gebundene Verschiebung.','', 'Vorgegebene Deutung: ≥0,8 erklärt Zusatz nicht; 0,5-<0,8 teilweise; <0,5 wesentlicher Teil möglicherweise Messartefakt. Punktschätzung und KI getrennt; eine Kategorie ist eine Modell-Sensitivität, keine nachgewiesene Artefaktfraktion.', '', '## 5. Prüfstatus und Grenzen','', 'P01a: Input-/Code-/Outputbindung, aktueller Inhalt, keine historische Releaseattestation. P01b: Original B3 und unveränderte Nullsample-Szenarien; LUDB-Fehlerformel Produktion minus Experte. P01c: Signalsnapshot-Gate je EKG; Status siehe oben. P03: Personen, EKGs, LUDB-Records und Beats getrennt. P05: Entwicklung allein. P08: Personenbootstrap für Morphologie, LUDB-/Personenbootstrap für Transport und korrigierte OR; HC3-Recordintervalle für Regression. Keine unabhängige Prüfung, keine klinische Freigabe.','', '| Falle | Status | Begründung |','|---|---|---|','| F1 | eingeschränkt | LVEF unabhängig vom Marker; F/Winkel teilen Schleifen; T-Dauer ist selbst delineationsabhängig. |','| F2 | eingeschränkt | Echo-verifizierte Krankenhaus-Complete-cases; keine Populationsprävalenz/PPV. |','| F3 | nicht_zutreffend | Keine Arbeitspunktoptimierung, feste EF-Grenze. |','| F4 | eingeschränkt | Explorative feste Sensitivitäten, nominale KI, interne Folds keine unabhängige Bestätigung. |','| F5 | offen | Referenz-/Morphologie-/Korrekturverfügbarkeit kann informativ sein. |','| F6 | eingeschränkt | Gebundenes B3 mit stetigem Winkel; keine vollständige flexible Komparator-/Messfehlermodellierung. |','| F7 | offen | Echo-Verifikationsbias, LUDB-Recordmittel nicht gleich MIMIC-Grenzfehler. |','| F8 | offen | SNR proxy-/filterabhängig, Delineationsfehler kann von weiteren unbeobachteten Merkmalen abhängen. |','', 'LUDB ist nicht MIMIC. Experten-T-Ende selbst unsicher, globale Extremfusion systematisch anders als mediane Grenze. Kein direktes MIMIC-Experten-T-Ende, keine kausal identifizierte EF-Abhängigkeit des Fehlers. Ein lineares Amplituden-/Flachheitsmodell mit niedrigem R² deckt keine EF-spezifischen Fehler jenseits seiner Kovariaten ab. Korrektur gemeinsamer Fehler kann die Kopplung verändern; ein stabiler Rest beweist keine eigenständige Biologie. Kein Quellenvergleich als „bestätigt durch“.','', 'Widerlegen/begrenzen würden eine direkte Expertenprüfung auf verblindeten Entwicklungs-EKGs mit größerer EF-spezifischer Fehlerdifferenz, ein transportgerechtes nichtlineares Fehlermodell mit sinkendem Zusatz, eine falsche Einheit/Signalbindung oder Scheitern der Äquivalenz. Offene Chance: direkte EF-stratifizierte menschliche Grenzadjudikation, ohne Öffnung der Testmenge. Quellenfehler-Kandidaten: kein neuer Literaturfehler; QRS/PR-Definition des loop_snr_proxy ist eine interne Benennungsgrenze.','', '## 6. Englische Textbausteine für B','', '**Methods.** In the development and internal validation folds, we compared spatial T-wave peak magnitude, T duration, amplitude-to-duration ratio and a T-segment noise proxy between LVEF <40% and ≥40%, using person-level bootstrap intervals. A record-level robust linear model related production-minus-expert T-end error in LUDB to T-wave magnitude and flatness. Model-based shifts were quantised to the production sampling grid; signal recomputation required exact unperturbed marker agreement, and paired bootstrap models retained the fixed development scaling.','']
    if complete:
        rr=[r for r in models if r['scenario']=='corrected']
        text.append('**Results.** '+ '; '.join(f"In {r['fold']}, the corrected Fréchet odds ratio beyond the spatial QRS-T angle was {num(r['or'])} (95% CI {interval_en(r['or_ci95'])}), retaining {num(100*r['remaining_log_or_fraction'])}% of the original log odds ratio" for r in rr)+'.')
    else:text.append('**Results.** T-wave duration differed between EF groups, but the individual correction could not be evaluated because unperturbed production marker equivalence failed; no corrected odds ratio was inferred.')
    text += ['', '**Limitations.** LUDB calibration does not establish transportability to MIMIC or a causal EF-dependent measurement error; expert T-end labels are uncertain, the noise measure is a proxy, and sub-sample group shifts quantised to zero do not exclude genuine differential errors.','', '## 7. Rechenbelege und Abgabe','', 'Serielle Phasen: `aw166_start.ps1 inventory`, `prepare`, `morphology`, `smoke`, `ludb`, `signals -Detached`, `models`, `morphology`, `report`. Vorgeschriebene Python-Umgebung, Speicherprüfung vor jedem Start, private Status-/Checkpointdateien. Signalphase: ein Python-Prozess, vier Recordthreads, native Threads=1; FeatureContext im gebundenen Release ist threading.local. Bereits seriell berechnete Checkpoints wurden beim Threadwechsel exakt gegengeprüft, bevor sie neu gebunden wurden. Nur eigener Signal-PID beim Wechsel beendet. Personenkennungen und Individualsignalwerte ausschließlich <local path>. Keine gebundene Eingabe geändert, keine Installation/Außenkommunikation.','', 'Erzeuger und exakte Quellen/Filter: prepare_manifest.json, ludb_records/*.json, calibration.json, signal_records/*.json, models_manifest.json; Aggregatwerte in morphology.json/model_results.json. Projekt-CSV enthält ausschließlich Gruppenaggregate/Definitionen, keine Kennungswerte. Hashmanifest report_manifest.json bindet Abschlussdateien.','', ('Selbsteinschätzung: hohe technische Sicherheit nach bestandenen Gates; wissenschaftlich begrenzter, modellabhängiger Sensitivitätsbefund.' if complete else 'Selbsteinschätzung: hohe Sicherheit der getrennten Morphologie-/LUDB-Aggregate; Übertragung ausdrücklich offen.')]
    rows.append({'section':'transport',**cal,'source':'calibration.json; aw166_run.py:calibrate'})
    from werkzeuge.b_test.aw166_reference import run as median_reference
    med=median_reference();rows.append(med)
    text += ['', '## Sensitivität: medianes Experten-T-Ende', '', 'Dieselben QRS-verankerten Paare, unveränderte Produktionsvorhersagen. Experten-T-Cluster und QRS-Referenzbeats aus öffentlichen Annotationen unabhängig rekonstruiert; jede bisherige extreme Referenzposition exakt geprüft. Lediglich das späteste Ende wird durch das Median-Ende der beteiligten Ableitungen ersetzt. Keine neue günstigere Paarwahl, kein Fehlertrimming.', '', f"Kalibrierung: {med['n_records']} Records / {med['n_beats']} Beatpaare; erwarteter Fehler <40 / ≥40: {num(med['mean_shift_low'])} / {num(med['mean_shift_high'])} ms. Gruppendifferenz {num(med['group_difference_ms'])} ms {interval(med['group_difference_ci95_ms'])}; Recordresidual-SD {num(med['residual_sd_record_ms'])} ms. Koeffizienten/HC3-KI in CSV. 500 gemeinsame Record-/Personenresamples, separater Strom SeedSequence([16620261013,3]). Dies ist die vorab benannte Referenz-/Kalibrierungssensitivität; die primäre MIMIC-Signalübertragung bleibt auf der extremen Expertenreferenz. Eine vollständige zweite MIMIC-Korrektur gegen Median-T-Ende wird nicht behauptet."]
    from werkzeuge.b_test.aw166_dispersion import run as dispersion
    dd=dispersion();rows.extend(dd)
    text += ['', '## Ergänzung: Streuung je LUDB-Morphologiequartil', '', 'Deskriptiver Darstellungsnachtrag nach Kalibrierung, vor korrigierten B3-Ergebnissen festgelegt: aw166_nachtrag1.md, SHA-256 '+sha(ROOT/'werkzeuge/b_test/aw166_nachtrag1.md')+'. Keine Änderung des Hauptfehlermodells. Alle nominalen 95%-KI und Quartilgrenzen in der CSV; jede Bootstrapziehung erneuert die LUDB-Regressionskoeffizienten. Innerhalb-Record-RMS-SD ist die Wurzel der mittleren beobachteten Beatfehlervarianz, keine latente reine Messfehlervarianz. Beide Streuungen enthalten Expertenreferenzunsicherheit.', '', '| Maß / Quartil | Records / Beats | erwarteter Fehler ms | SD Recordmittelresiduen ms | RMS der Within-Record-SD ms |', '|---|---:|---:|---:|---:|']
    for r in dd:
        cc=r['ci95']
        text.append(f"| {r['measure']} / Q{r['quartile']} | {r['n_records']} / {r['n_beats']} | {num(r['expected_mean_error_ms'])} {interval([cc[0][0],cc[1][0]])} | {num(r['residual_sd_record_mean_ms'])} {interval([cc[0][1],cc[1][1]])} | {num(r['within_record_rms_sd_ms'])} {interval([cc[0][2],cc[1][2]])} |")
    text += ['', 'Die Within-Record-SD benötigt mindestens zwei endliche Beatfehler je Record; n_records_with_sd steht gesondert in der CSV. Die Korrektur entfernt den erwarteten Mittelwertfehler. Differenzielle Grenzfehlerstreuung wird nicht zusätzlich zufällig in MIMIC-Signale eingespielt; eine stabile OR schließt deshalb einen Varianzartefaktmechanismus nicht aus. T-Dauer/Flachheit werden mit dem Produktionst-Ende gemessen und sind selbst mit dessen Fehler gekoppelt. QTcF enthält weiterhin die ursprüngliche Grenze: Dies ist eine gezielte Fréchet-/Winkel-Sensitivität, kein vollständig synchronisiertes Fiduzial-Fehlermodell.']
    text += ['', 'Technischer Nachtrag zur Rechenäquivalenz: Der Zielkern verwendet die unveränderte Produktions-Segmentvorbereitung und Normierung sowie eine unabhängige, exakt gleiche Max/Min-Fréchet-Rekursion über Antidiagonalen. Originalbündel und Zielkern werden für jede unverschobene und jede zentrale korrigierte Aufzeichnung ohne numerische Toleranz verglichen; frühere vollständige Bootstrap-Samplegitter dienen als zusätzliche Vergleichsquelle. Die erste Optimierung hatte das separate Produktions-Konfidenzgate für T übersehen. Dies betraf die Missingness einzelner Bootstrapverschiebungen und wurde vor Modellschätzung korrigiert. Betroffene Checkpoints sind neu gerechnet und direkt gegen das ursprüngliche Bündel geprüft; die technischen Zwischenstände wurden nicht als Befund veröffentlicht. Die mehrfach wiederholte Prüfung aller Importpfade wurde innerhalb des isolierten Prozesses zwischengespeichert; Anfang/Ende prüfen denselben gebundenen Release. Profil-/Diagnosephasen mit wenigen Aufzeichnungen sind technische Kontrollen, kein Ersatz für das vollständige H1-Fallset.']
    text += ['', 'Die Zeile original_full_reference ist die gesamte unkorrigierte H1-Referenz mit personenrobustem CR1-Wald-KI; sie wird nicht als gepaarter Korrekturvergleich ausgegeben. Original/Korrekturvergleiche verwenden ihr gemeinsames Hauptfallset. Ein Ausfall eines korrigierten Bootstrapfits invalidiert dessen Intervallziehung; die gleichzeitig schätzbare unkorrigierte/Nullsample-Referenz wird separat vollständig beibehalten. Die vorgegebene Kategorie des korrigierten Punktschätzers ist bei nicht schätzbarem Korrektur-KI ausdrücklich kein bestandener Robustheitsnachweis.']
    text += ['', 'Zufallsströme: LUDB-Kalibrierung/Transport seed 16620261013; Outcome-Personenbootstrap pro Fold mit SeedSequence([16620261013, 2, fold_index]). Dadurch sind die Personenziehungen von den Kalibrierungsziehungen getrennt; Original und Korrektur verwenden innerhalb eines Draws dieselben Personengewichte. Die Kalibrierungsquelle ist in beiden Folds gemeinsam und daher keine unabhängige zweite externe Quelle.']
    fields=sorted(set().union(*(r.keys() for r in rows)))
    csvpath=ROOT/'nachrechnung/b_tende_ef.csv'
    with csvpath.open('w',newline='',encoding='utf8') as handle:
        writer=csv.DictWriter(handle,fieldnames=fields);writer.writeheader()
        for r in rows:writer.writerow({k:json.dumps(v,ensure_ascii=False) if isinstance(v,(list,dict)) else v for k,v in r.items()})
    report=ROOT/'nachrechnung/B_TENDE_EF_AW166.md';report.write_text('\n'.join(text)+'\n',encoding='utf8')
    files=[str(p.relative_to(ROOT)).replace('\\','/') for p in sorted((ROOT/'werkzeuge/b_test').glob('aw166_*')) if p.is_file()]
    submission=['# Abgabe AW-166','', '13.10.2026 · MS/PR · Deutsch','', '## Ergebnis', '', ('Analysen abgeschlossen; Ergebnis und Kategorien mit KI im Bericht. Keine unabhängige Testprüfung oder Publikationsfreigabe.' if complete else 'Morphologie und LUDB-Kalibrierung abgeschlossen. Individuelle Übertragung wegen gescheitertem Äquivalenzgate nicht schätzbar; Auftrag mit dieser konkreten technischen Grenze abgegeben, keine Vollständigkeits-/Robustheitsbehauptung.'),'',f"Erwartete EF-Gruppendifferenz des T-Ende-Fehlers: {num(cal['group_difference_ms'])} ms, 95%-KI {interval(cal['group_difference_ci95_ms'])}; diskretisierte Gruppen-/Worst-Case-Sensitivitäten 0 Samples. T-Dauer verfehlt das Abbruchgate. Details: nachrechnung/B_TENDE_EF_AW166.md und b_tende_ef.csv.",'','## Neue/geänderte Dateien','']
